:root {
  --bg-sage: #f2f5f1;
  --card-bg: #ffffff;
  --text-main: #2d3732;
  --text-muted: #5c6b63;
  --primary: #4a6b5d;
  --primary-hover: #3b554a;
  --border-color: #d1dcce;
  --accent: #d4a373;
  --shadow: 0 4px 12px rgba(74, 107, 93, 0.08);
  --radius: 12px;
}
* { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
body { background-color: var(--bg-sage); color: var(--text-main); line-height: 1.5; padding: 24px; display: flex; justify-content: center; }
.app-container { width: 100%; max-width: 900px; display: flex; flex-direction: column; gap: 24px; }
header { background: var(--card-bg); padding: 24px; border-radius: var(--radius); border: 1px solid var(--border-color); box-shadow: var(--shadow); }
header h1 { font-size: 1.8rem; color: var(--primary); margin-bottom: 6px; font-weight: 700; }
header p { color: var(--text-muted); font-size: 0.95rem; }
main { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
@media (max-width: 768px) { main { grid-template-columns: 1fr; } }
.card { background: var(--card-bg); padding: 24px; border-radius: var(--radius); border: 1px solid var(--border-color); box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 16px; }
.card h2 { font-size: 1.2rem; color: var(--primary); border-bottom: 2px solid var(--bg-sage); padding-bottom: 8px; }
.form-group { display: flex; flex-direction: column; gap: 6px; }
label { font-size: 0.85rem; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
input { padding: 10px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 1rem; color: var(--text-main); background: #fafbfc; transition: border-color 0.2s; }
input:focus { outline: none; border-color: var(--primary); background: #fff; }
button { padding: 12px 20px; border: none; border-radius: 8px; font-size: 1rem; font-weight: 600; cursor: pointer; transition: background 0.2s, opacity 0.2s; display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.btn-primary { background: var(--primary); color: white; }
.btn-primary:hover:not(:disabled) { background: var(--primary-hover); }
.btn-secondary { background: #e2e8f0; color: var(--text-main); }
.btn-secondary:hover:not(:disabled) { background: #cbd5e1; }
button:disabled { opacity: 0.6; cursor: not-allowed; }
.result-box { background: var(--bg-sage); padding: 16px; border-radius: 8px; border: 1px dashed var(--primary); display: flex; flex-direction: column; gap: 6px; }
.result-value { font-size: 1.5rem; font-weight: 700; color: var(--primary); }
.saved-list { display: flex; flex-direction: column; gap: 12px; max-height: 400px; overflow-y: auto; }
.saved-item { background: #fafbfc; padding: 12px 16px; border-radius: 8px; border: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; }
.saved-info { display: flex; flex-direction: column; gap: 2px; }
.saved-title { font-weight: 600; color: var(--text-main); }
.saved-detail { font-size: 0.85rem; color: var(--text-muted); }
.alert { padding: 12px; border-radius: 8px; font-size: 0.9rem; background: #fff3cd; color: #856404; border: 1px solid #ffeeba; }
.alert-error { background: #f8d7da; color: #721c24; border: 1px solid #f5c6cb; }
.empty-state { text-align: center; color: var(--text-muted); padding: 24px; font-style: italic; }

