(async function() {
  let state = await lf.ready;
  let lastResult = null;

  const elIngredient = document.getElementById('ingredient');
  const elAmount = document.getElementById('amount');
  const elOriginal = document.getElementById('originalServings');
  const elTarget = document.getElementById('targetServings');
  const elResult = document.getElementById('scaled-result');
  const elCalcError = document.getElementById('calc-error');
  const btnCalculate = document.getElementById('btn-calculate');
  const btnSave = document.getElementById('btn-save');
  const previewNotice = document.getElementById('preview-notice');
  const savedList = document.getElementById('saved-list');

  function render(currentState) {
    if (!currentState.permissions.canUseTools) {
      previewNotice.style.display = 'block';
      previewNotice.textContent = 'Preview tools remain disabled until Publish.';
    } else {
      previewNotice.style.display = 'none';
    }

    const records = currentState.records || [];
    if (records.length === 0) {
      savedList.innerHTML = '<div class="empty-state">No saved calculations yet.</div>';
    } else {
      savedList.innerHTML = '';
      records.forEach(rec => {
        const v = rec.values;
        const item = document.createElement('div');
        item.className = 'saved-item';

        const info = document.createElement('div');
        info.className = 'saved-info';

        const title = document.createElement('div');
        title.className = 'saved-title';
        title.textContent = v.ingredient || 'Unnamed Ingredient';

        const detail = document.createElement('div');
        detail.className = 'saved-detail';
        detail.textContent = `Scaled: ${v.scaledAmount} (from ${v.amount} for ${v.originalServings} to ${v.targetServings} servings)`;

        info.appendChild(title);
        info.appendChild(detail);
        item.appendChild(info);

        const delBtn = document.createElement('button');
        delBtn.className = 'btn-secondary';
        delBtn.textContent = 'Delete';
        delBtn.style.padding = '6px 12px';
        delBtn.style.fontSize = '0.85rem';
        delBtn.addEventListener('click', async () => {
          try {
            state = await lf.remove(rec.id);
            render(state);
          } catch (e) {
            alert('Failed to delete: ' + (e.message || e));
          }
        });
        item.appendChild(delBtn);

        savedList.appendChild(item);
      });
    }
  }

  btnCalculate.addEventListener('click', async () => {
    elCalcError.style.display = 'none';
    elCalcError.textContent = '';

    const ingredient = elIngredient.value.trim();
    const amount = parseFloat(elAmount.value);
    const originalServings = parseFloat(elOriginal.value);
    const targetServings = parseFloat(elTarget.value);

    if (!ingredient) {
      elCalcError.textContent = 'Please enter an ingredient name.';
      elCalcError.style.display = 'block';
      return;
    }
    if (isNaN(amount) || isNaN(originalServings) || isNaN(targetServings)) {
      elCalcError.textContent = 'Please enter valid numbers for amount and servings.';
      elCalcError.style.display = 'block';
      return;
    }
    if (originalServings <= 0) {
      elCalcError.textContent = 'Original servings must be positive.';
      elCalcError.style.display = 'block';
      return;
    }

    if (!state.permissions.canUseTools) {
      elCalcError.textContent = 'Preview tools remain disabled until Publish.';
      elCalcError.style.display = 'block';
      return;
    }

    btnCalculate.disabled = true;
    btnCalculate.textContent = 'Calculating...';

    try {
      const res = await lf.runTool('scale_recipe', 1, {
        amount,
        originalServings,
        targetServings
      });
      lastResult = res.result.scaledAmount;
      elResult.textContent = lastResult;
      btnSave.disabled = false;
    } catch (e) {
      elCalcError.textContent = 'Calculation failed: ' + (e.message || e);
      elCalcError.style.display = 'block';
    } finally {
      btnCalculate.disabled = false;
      btnCalculate.textContent = 'Calculate Scale';
    }
  });

  btnSave.addEventListener('click', async () => {
    if (lastResult === null) return;
    try {
      const values = {
        ingredient: elIngredient.value.trim(),
        amount: parseFloat(elAmount.value),
        originalServings: parseFloat(elOriginal.value),
        targetServings: parseFloat(elTarget.value),
        scaledAmount: lastResult
      };
      state = await lf.create(values);
      render(state);
      btnSave.disabled = true;
    } catch (e) {
      alert('Failed to save calculation: ' + (e.message || e));
    }
  });

  lf.subscribe(nextState => {
    state = nextState;
    render(state);
  });

  render(state);
  await lf.reportReady();
})();

