function run(input, api) {
  if (input.originalServings <= 0) {
    throw new Error("originalServings must be positive");
  }
  const raw = (input.amount * input.targetServings) / input.originalServings;
  const scaledAmount = Math.round(raw * 100) / 100;
  return { scaledAmount };
}
